using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.IO;
using System.IO.Compression;
using System.Linq;
using System.Security.Cryptography;
using System.Text.RegularExpressions;
using System.Web.Script.Serialization;

namespace ReFix.Updating {
 public sealed class BundleFile { public string Path{get;set;} public string Sha256{get;set;} }
 public sealed class BundleManifest { public int SchemaVersion{get;set;} public string Version{get;set;} public List<BundleFile> Files{get;set;} }
 public sealed class UpdatePlan {
  public int SchemaVersion{get;set;} public string Target{get;set;} public string Work{get;set;} public string Stage{get;set;} public string ManifestHash{get;set;} public string Version{get;set;}
  public int ParentPid{get;set;} public long ParentStartedUtc{get;set;} public string ParentPath{get;set;}
  public bool RestartInBackground{get;set;}
 }
 public static class UpdateEngine {
  public static readonly string[] Required={"HUB-ReFIX.exe","HUB-ReFIX.exe.config","HUB-ReFIX.Core.exe","HUB-ReFIX.Core.exe.config","ReFix.Shared.dll","ReFix.UpdateHelper.exe","catalog.json","README.md","tools/Install.ps1","tools/Install.cmd","tools/Uninstall.ps1","tools/Uninstall.cmd"};
  public const long MaxArchive=128L*1024*1024, MaxExpanded=512L*1024*1024;
  public static JavaScriptSerializer Json(){return new JavaScriptSerializer{MaxJsonLength=1024*1024,RecursionLimit=32};}
  public static string Read(string path){if(new FileInfo(path).Length>1024*1024)throw new InvalidDataException("Oversized metadata.");return File.ReadAllText(path);}
  public static void Relative(string path){if(string.IsNullOrWhiteSpace(path)||path.Length>200||Path.IsPathRooted(path)||path.Contains(":")||path.Contains("\\"))throw new InvalidDataException("Unsafe relative path.");foreach(string p in path.Split('/'))if(p==""||p=="."||p==".."||p.EndsWith(".")||p.EndsWith(" ")||p.IndexOfAny(Path.GetInvalidFileNameChars())>=0||Regex.IsMatch(p,"^(con|prn|aux|nul|com[0-9]|lpt[0-9])($|\\.)",RegexOptions.IgnoreCase))throw new InvalidDataException("Unsafe path component.");}
  public static string Full(string path){return Path.GetFullPath(path).TrimEnd(Path.DirectorySeparatorChar,Path.AltDirectorySeparatorChar);}
  public static bool Under(string root,string path){return Full(path).StartsWith(Full(root)+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase);}
  public static string Inside(string root,string path){Relative(path);string result=Path.GetFullPath(Path.Combine(root,path.Replace('/',Path.DirectorySeparatorChar)));if(!Under(root,result))throw new InvalidDataException("Path escaped root.");NoLinks(result);return result;}
  public static void NoLinks(string path){string current=Path.GetFullPath(path);while(!string.IsNullOrEmpty(current)){if((File.Exists(current)||Directory.Exists(current))&&(File.GetAttributes(current)&FileAttributes.ReparsePoint)!=0)throw new InvalidDataException("Links are forbidden.");current=Path.GetDirectoryName(current);}}
  public static string Hash(string path){NoLinks(path);using(var sha=SHA256.Create())using(var input=File.OpenRead(path))return BitConverter.ToString(sha.ComputeHash(input)).Replace("-","").ToLowerInvariant();}
  public static bool IsHash(string hash){return Regex.IsMatch(hash??"","^[a-fA-F0-9]{64}$");}
  public static void Version(string version){System.Version v;if(!Regex.IsMatch(version??"","^[0-9]{1,5}\\.[0-9]{1,5}\\.[0-9]{1,5}(\\.[0-9]{1,5})?$")||!System.Version.TryParse(version,out v))throw new InvalidDataException("Invalid version.");}
  public static BundleManifest Manifest(string root,bool verify){
   var m=Json().Deserialize<BundleManifest>(Read(Inside(root,"bundle-files.json")));if(m==null||m.SchemaVersion!=1||m.Files==null||m.Files.Count==0||m.Files.Count>256||!Regex.IsMatch(m.Version??"",@"^(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)$"))throw new InvalidDataException("Invalid bundle manifest.");Version(m.Version);var seen=new HashSet<string>(StringComparer.OrdinalIgnoreCase);long total=0;
   foreach(var f in m.Files){if(f==null||f.Path==null)throw new InvalidDataException("Invalid bundle entry.");f.Path=f.Path.Replace('\\','/');string path=Inside(root,f.Path);if(!seen.Add(f.Path)||!Regex.IsMatch(f.Sha256??"","^[a-f0-9]{64}$")||(!Required.Contains(f.Path)&&!Regex.IsMatch(f.Path,@"^packages/(quiet-mixer|quick-note)-"+Regex.Escape(m.Version)+@"\.zip$")))throw new InvalidDataException("Invalid or reserved bundle entry.");if(verify){total=checked(total+new FileInfo(path).Length);if(total>MaxExpanded||!Hash(path).Equals(f.Sha256,StringComparison.OrdinalIgnoreCase))throw new InvalidDataException("Bundle hash mismatch: "+f.Path);}}
   foreach(string required in Required.Concat(new[]{"packages/quiet-mixer-"+m.Version+".zip","packages/quick-note-"+m.Version+".zip"}))if(!seen.Contains(required))throw new InvalidDataException("Missing required bundle file: "+required);
   if(verify)ValidateCatalog(root,m);
   return m;
  }
  static void ValidateCatalog(string root,BundleManifest manifest){var catalog=Json().Deserialize<Dictionary<string,object>>(Read(Inside(root,"catalog.json")));object schema,raw;if(catalog==null||!catalog.TryGetValue("SchemaVersion",out schema)||Convert.ToString(schema)!="1"||!catalog.TryGetValue("Modules",out raw))throw new InvalidDataException("Invalid bundled catalog.");var modules=raw as System.Collections.IEnumerable;var ids=new HashSet<string>();if(modules==null)throw new InvalidDataException("Invalid catalog modules.");foreach(object item in modules){var module=item as Dictionary<string,object>;object id,version,hash;if(module==null||!module.TryGetValue("Id",out id)||!module.TryGetValue("Version",out version)||!module.TryGetValue("Sha256",out hash))throw new InvalidDataException("Invalid catalog entry.");string name=Convert.ToString(id);if((name!="quiet-mixer"&&name!="quick-note")||!ids.Add(name)||Convert.ToString(version)!=manifest.Version)throw new InvalidDataException("Catalog module identity mismatch.");var file=manifest.Files.Single(f=>f.Path=="packages/"+name+"-"+manifest.Version+".zip");if(Convert.ToString(hash)!=file.Sha256)throw new InvalidDataException("Catalog package hash mismatch.");}if(ids.Count!=2)throw new InvalidDataException("Missing bundled catalog modules.");}
  public static void Extract(string archive,string root){
   if(new FileInfo(archive).Length>MaxArchive)throw new InvalidDataException("Oversized archive.");NoLinks(root);Directory.CreateDirectory(root);var seen=new HashSet<string>(StringComparer.OrdinalIgnoreCase);long total=0;
   using(var zip=ZipFile.OpenRead(archive)){if(zip.Entries.Count>4096)throw new InvalidDataException("Too many ZIP entries.");const string wrapper="HUB-ReFIXwin11/";bool wrapped=zip.Entries.Any(e=>e.FullName.StartsWith(wrapper,StringComparison.Ordinal));foreach(var e in zip.Entries){string name=e.FullName;if(wrapped){if(!name.StartsWith(wrapper,StringComparison.Ordinal))throw new InvalidDataException("Mixed archive roots.");name=name.Substring(wrapper.Length);if(name==""){if(!seen.Add(wrapper)||((e.ExternalAttributes>>16)&0xF000)==0xA000||(e.ExternalAttributes&0x400)!=0||e.Length!=0)throw new InvalidDataException("Invalid ZIP root.");continue;}}name=name.TrimEnd('/');string dest=Inside(root,name);if(!seen.Add(name)||((e.ExternalAttributes>>16)&0xF000)==0xA000||(e.ExternalAttributes&0x400)!=0)throw new InvalidDataException("Duplicate or linked ZIP entry.");total=checked(total+e.Length);if(total>MaxExpanded)throw new InvalidDataException("Oversized expanded archive.");if(e.FullName.EndsWith("/")){Directory.CreateDirectory(dest);continue;}Directory.CreateDirectory(Path.GetDirectoryName(dest));using(var input=e.Open())using(var output=new FileStream(dest,FileMode.CreateNew)){byte[] buffer=new byte[32768];long count=0;int n;while((n=input.Read(buffer,0,buffer.Length))>0){count+=n;if(count>e.Length||count>MaxExpanded)throw new InvalidDataException("Oversized ZIP entry.");output.Write(buffer,0,n);}if(count!=e.Length)throw new InvalidDataException("Truncated ZIP entry.");}}}
   var manifest=Manifest(root,true);var owned=new HashSet<string>(manifest.Files.Select(f=>f.Path),StringComparer.OrdinalIgnoreCase);owned.Add("bundle-files.json");foreach(string file in Directory.GetFiles(root,"*",SearchOption.AllDirectories))if(!owned.Contains(file.Substring(Full(root).Length+1).Replace('\\','/')))throw new InvalidDataException("Unlisted archive file.");
  }
  public static UpdatePlan LoadPlan(string path){NoLinks(path);var p=Json().Deserialize<UpdatePlan>(Read(path));ValidatePlan(p);if(!string.Equals(Full(path),Inside(p.Work,"plan.json"),StringComparison.OrdinalIgnoreCase))throw new InvalidDataException("Plan is outside work directory.");return p;}
  public static void ValidatePlan(UpdatePlan p){if(p==null||p.SchemaVersion!=1||!IsHash(p.ManifestHash)||p.ParentPid<=0||p.ParentStartedUtc<=0)throw new InvalidDataException("Invalid update plan.");Version(p.Version);p.Target=Full(p.Target);p.Work=Full(p.Work);p.Stage=Full(p.Stage);if(p.Target==Path.GetPathRoot(p.Target).TrimEnd('\\')||Under(p.Target,p.Work)||Under(p.Work,p.Target)||p.Target.Equals(p.Work,StringComparison.OrdinalIgnoreCase)||!p.Stage.Equals(Inside(p.Work,"payload"),StringComparison.OrdinalIgnoreCase)||!p.ParentPath.Equals(Inside(p.Target,"HUB-ReFIX.Core.exe"),StringComparison.OrdinalIgnoreCase))throw new InvalidDataException("Invalid update roots or parent.");NoLinks(p.Target);NoLinks(p.Work);NoLinks(p.Stage);}
  public static void WaitForParent(UpdatePlan p){
   try{using(var parent=Process.GetProcessById(p.ParentPid)){if(parent.HasExited)return;try{if(parent.StartTime.ToUniversalTime().Ticks!=p.ParentStartedUtc)throw new InvalidDataException("Parent PID was reused.");if(!string.Equals(Full(parent.MainModule.FileName),Full(p.ParentPath),StringComparison.OrdinalIgnoreCase))throw new InvalidDataException("Parent executable differs.");}catch(InvalidOperationException){if(parent.HasExited)return;throw;}if(!parent.WaitForExit(60000))throw new TimeoutException("HUB did not exit; update was cancelled.");}}catch(ArgumentException){}
  }
  // Optional fault callback is used by isolated filesystem tests, never by the executable.
  public static void Apply(UpdatePlan p,Action<int> afterWrite){
   ValidatePlan(p);if(!Hash(Inside(p.Stage,"bundle-files.json")).Equals(p.ManifestHash,StringComparison.OrdinalIgnoreCase))throw new InvalidDataException("Prepared manifest changed.");var next=Manifest(p.Stage,true);if(next.Version!=p.Version)throw new InvalidDataException("Prepared version changed.");var old=Manifest(p.Target,false);
   var prior=new HashSet<string>(old.Files.Select(f=>f.Path),StringComparer.OrdinalIgnoreCase);prior.Add("bundle-files.json");var incoming=new HashSet<string>(next.Files.Select(f=>f.Path),StringComparer.OrdinalIgnoreCase);incoming.Add("bundle-files.json");var touched=new HashSet<string>(prior,StringComparer.OrdinalIgnoreCase);touched.UnionWith(incoming);
   string marker=Inside(p.Target,"installation.json");Dictionary<string,object> setupMarker=null;if(File.Exists(marker)){var existing=Json().Deserialize<Dictionary<string,object>>(Read(marker));object mode;if(existing!=null&&existing.TryGetValue("Mode",out mode)&&Convert.ToString(mode)=="Setup"){setupMarker=existing;touched.Add("installation.json");}}
   foreach(string rel in incoming){string dest=Inside(p.Target,rel);if(!prior.Contains(rel)&&(File.Exists(dest)||Directory.Exists(dest)))throw new IOException("Update would overwrite an unknown file: "+rel);}
   string backup=Inside(p.Work,"backup");if(Directory.Exists(backup)||File.Exists(backup))throw new IOException("Backup already exists.");Directory.CreateDirectory(backup);var existed=new HashSet<string>(StringComparer.OrdinalIgnoreCase);
   foreach(string rel in touched){string source=Inside(p.Target,rel);if(File.Exists(source)){string dest=Inside(backup,rel);Directory.CreateDirectory(Path.GetDirectoryName(dest));File.Copy(source,dest,false);existed.Add(rel);}}
   var changed=new List<string>();try{int writes=0;foreach(string rel in touched){string dest=Inside(p.Target,rel);changed.Add(rel);if(rel=="installation.json"&&setupMarker!=null){setupMarker["Version"]=next.Version;File.WriteAllText(dest,Json().Serialize(setupMarker));}else if(incoming.Contains(rel)){Directory.CreateDirectory(Path.GetDirectoryName(dest));File.Copy(Inside(p.Stage,rel),dest,true);}else if(File.Exists(dest))File.Delete(dest);if(afterWrite!=null)afterWrite(++writes);}Manifest(p.Target,true);}
   catch(Exception failure){var errors=new List<Exception>();for(int i=changed.Count-1;i>=0;i--)try{string rel=changed[i],dest=Inside(p.Target,rel);if(existed.Contains(rel))File.Copy(Inside(backup,rel),dest,true);else if(File.Exists(dest))File.Delete(dest);}catch(Exception restore){errors.Add(restore);}if(errors.Count>0){errors.Insert(0,failure);throw new AggregateException("Update failed and rollback needs repair; backup retained at "+backup,errors);}throw;}
  }
  internal static void SaveRestartMode(UpdatePlan p,string path,bool? restartInBackground){ValidatePlan(p);if(!string.Equals(Full(path),Inside(p.Work,"plan.json"),StringComparison.OrdinalIgnoreCase))throw new InvalidDataException("Plan is outside work directory.");NoLinks(path);if(!restartInBackground.HasValue)return;p.RestartInBackground=restartInBackground.Value;File.WriteAllText(path,Json().Serialize(p),new System.Text.UTF8Encoding(false));}
  internal static ProcessStartInfo RestartStartInfo(UpdatePlan p){string exe=Inside(p.Target,"HUB-ReFIX.exe");return new ProcessStartInfo(exe,p.RestartInBackground?"--background":""){UseShellExecute=true,WorkingDirectory=p.Target};}
  public static void Restart(UpdatePlan p){Process.Start(RestartStartInfo(p));}
 }
}
